#!/usr/bin/env python3
import sys
import re
from pathlib import Path

def promote_book(raw_path_str, target_path_str, title="Book", author="Unknown", tags="#Sci-Fi"):
    raw_path = Path(raw_path_str)
    target_path = Path(target_path_str)

    if not raw_path.exists():
        print(f"Error: {raw_path} does not exist.")
        sys.exit(1)

    target_path.parent.mkdir(parents=True, exist_ok=True)

    existing_content = target_path.read_text(encoding='utf-8') if target_path.exists() else ""
    conceptual_links = ""
    # Find where the conceptual links start
    match = re.search(r'(## .*?🔗 Conceptual Links & Connections.*)', existing_content, re.DOTALL)
    if match:
        links_body = match.group(1)
        # Strip out the old header and replace with the new elegant format
        links_body = re.sub(r'^## .*?🔗 Conceptual Links & Connections.*?\n', '## <span style="color:#e5c07b">🔗 Conceptual Links & Connections</span>\n', links_body)
        conceptual_links = "\n\n---\n\n" + links_body

    content = raw_path.read_text(encoding='utf-8')
    blocks = content.split('<!-- hash:')
    parsed = []

    for block in blocks[1:]:
        lines = [l.strip() for l in block.split('\n') if l.strip()]
        if len(lines) < 2: continue

        hash_val = lines[0].replace('-->', '').strip()
        quote = ""
        meta = ""
        for line in lines[1:]:
            if line.startswith('>-') or line.startswith('> *-'):
                meta = line.replace('>-', '').replace('> *-', '').replace('*', '').strip()
            elif line.startswith('>'):
                quote += line.replace('>', '').strip() + " "
        quote = quote.strip()

        loc_match = re.search(r'Location ([\d-]+)', meta)
        loc = loc_match.group(1) if loc_match else "Unknown Location"
        page_match = re.search(r'page (\d+)', meta)
        page = int(page_match.group(1)) if page_match else 0

        if "Your Note" in meta:
            parsed.append({'type': 'note', 'text': quote, 'loc': loc, 'page': page})
        else:
            parsed.append({'type': 'highlight', 'text': quote, 'loc': loc, 'page': page})

    collapsed = []
    for item in parsed:
        if item['type'] == 'note':
            if collapsed and collapsed[-1]['type'] == 'note':
                if len(item['text']) > len(collapsed[-1]['text']):
                    collapsed[-1]['text'] = item['text']
                else:
                    collapsed[-1]['text'] = item['text']
            else:
                collapsed.append(item)
        else:
            collapsed.append(item)

    # Specialized grouping for Snow Crash based on title to keep the semantic groups
    if "Snow Crash" in title:
        metaverse_quotes = []
        language_quotes = []
        society_quotes = []
        programming_quotes = []

        for i, item in enumerate(collapsed):
            if item['type'] == 'note': continue
            text_lower = item['text'].lower()
            note_text = ""
            if i + 1 < len(collapsed) and collapsed[i+1]['type'] == 'note':
                note_text = collapsed[i+1]['text']
            entry = {"loc": item['loc'], "page": item['page'], "text": item['text'], "note": note_text}

            if any(k in text_lower for k in ['metaverse', 'daemon', 'avatar', 'goggle', 'optic']):
                metaverse_quotes.append(entry)
            elif any(k in text_lower for k in ['babel', 'asherah', 'enki', 'language', 'sumer', 'virus']):
                language_quotes.append(entry)
            elif any(k in text_lower for k in ['hacker', 'machine language', 'program']):
                programming_quotes.append(entry)
            else:
                society_quotes.append(entry)

        groups = [
            ("1. The Metaverse and Technology", metaverse_quotes, "sec-1"),
            ("2. Language, Sumerian Myth, and Metaviruses", language_quotes, "sec-2"),
            ("3. Programming and Hackers", programming_quotes, "sec-3"),
            ("4. World and Society", society_quotes, "sec-4")
        ]
    else:
        groups = []
        entries = []
        for i, item in enumerate(collapsed):
            if item['type'] == 'note': continue
            note_text = ""
            if i + 1 < len(collapsed) and collapsed[i+1]['type'] == 'note':
                note_text = collapsed[i+1]['text']
            entries.append({"loc": item['loc'], "page": item['page'], "text": item['text'], "note": note_text})

        chunk_size = 10
        for i in range(0, len(entries), chunk_size):
            chunk = entries[i:i+chunk_size]
            min_page = min([e['page'] for e in chunk if e['page'] > 0] or [0])
            max_page = max([e['page'] for e in chunk if e['page'] > 0] or [0])

            if max_page > 0:
                if min_page == max_page:
                    sec_title = f"Page {min_page}"
                else:
                    sec_title = f"Pages {min_page}-{max_page}"
            else:
                sec_title = f"Part {i//chunk_size + 1}"

            groups.append((sec_title, chunk, f"sec-{i//chunk_size + 1}"))

    markdown = f"""# {title}

---
Tag(s): {tags}

---

**{author}**

* * *

"""

    # Generate collapsible Table of Contents using standard markdown block links
    toc = "> [!info]- 📑 Table of Contents\n"
    has_toc = False
    for sec_title, chunk, sec_id in groups:
        if chunk:
            has_toc = True
            toc += f"> - [{sec_title}](#{sec_id})\n"

    if has_toc:
        markdown += toc + "\n\n"

    def write_section(sec_title, entries, sec_id):
        if not entries: return ""
        # The elegant light yellow color. The invisible anchor allows smooth-scrolling without highlighting the chapter.
        sec = f"<a name=\"{sec_id}\" id=\"{sec_id}\"></a>\n"
        sec += f"## <span style=\"color:#e5c07b\">{sec_title}</span>\n\n"
        for e in entries:
            loc_str = f"Location {e['loc']}"
            if e['page'] > 0:
                loc_str = f"Page {e['page']} | " + loc_str

            sec += f"<span style=\"color:#888888\">{loc_str}</span>\n"
            sec += f"> <span style=\"color:#d4d4d4\">{e['text']}</span>\n"
            if e['note']:
                # The div explicitly moves it to the right and out of the blockquote cleanly
                sec += f"<div style=\"margin-left: 2em;\"><span style=\"color:#5db0d7\">↑ <b>Note:</b></span> <span style=\"color:#ffffff\">{e['note']}</span></div>\n"
            sec += "\n"
        return sec

    for sec_title, chunk, sec_id in groups:
        markdown += write_section(sec_title, chunk, sec_id)

    target_path.write_text(markdown + conceptual_links, encoding='utf-8')
    print(f"File promoted successfully to {target_path}")

if __name__ == '__main__':
    raw_path = sys.argv[1] if len(sys.argv) > 1 else '/home/zacmero/Documents/mero-vault/5_ Knowledge_Library/raw_book_notes/Snow Crash - Neal Stephenson.md'
    target_path = sys.argv[2] if len(sys.argv) > 2 else '/home/zacmero/Documents/mero-vault/5_ Knowledge_Library/Sci-Fi/Snow Crash.md'
    title = sys.argv[3] if len(sys.argv) > 3 else 'Snow Crash'
    author = sys.argv[4] if len(sys.argv) > 4 else 'Neal Stephenson'
    promote_book(raw_path, target_path, title, author, "#Sci-Fi #Cyberpunk")

